class DiagnosisProbe:
    def __init__(self, view, device):
        self.view, self.device = view, device

    def run_full_diagnosis(self, train_loader):
        module = self.view.model
        previous_mode = module.training
        try:
            module.eval()
            with no_grad():
                metrics = existing_embedding_and_margin_probes(train_loader)
                metrics.update(training_history_dependence_probes(train_loader))
            attach_valid_counts_and_unavailable_states(metrics)
            return {'metrics': metrics, 'metric_definitions': definitions(metrics)}
        finally:
            module.train(previous_mode)

# Separate optional audit; never called with test data.
def audit_validation(view, permitted_records, fixed_candidate_arrays):
    for category in FOUR_CATEGORIES:
        for user in permitted_records[category]:
            original = user.history
            candidates = fixed_candidate_arrays[category][user.id]
            variants = controlled_deletions_and_order_shuffles(original, seed=42)
            baseline = score(view, original, candidates)
            for variant in variants:
                changed = score(view, variant, candidates)
                record_paired_hits_ranks_and_overlap(baseline, changed)
    return category_effects_and_stratified_bootstrap_intervals()

